        if not table_elements:
            return 0
        table = table_elements[0]
        rows = table.xpath('.//tr')
        data = []
        for row in rows:
            cols = row.xpath('.//td/text() | .//th/text()')
            cols = [col.strip() for col in cols if col.strip()]
            if cols:
                data.append(cols)
        if not data:
            return 0
        df = pd.DataFrame(data)
    except Exception as e:
        raise ValueError(f"Error parsing HTML table: {e}")

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql('my_table', conn, if_exists='replace', index=False)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")

    return len(df)

